import { afterAll } from 'vitest';
import pool from '../config/database';

// Test Setup Configs Generated By Claude

const databaseUrl = process.env.DATABASE_URL;

if (process.env.NODE_ENV !== 'test') {
  throw new Error(
    'Backend tests must run with NODE_ENV=test.'
  );
}

if (!databaseUrl) {
  throw new Error(
    'DATABASE_URL must be configured for backend tests.'
  );
}

const parsedUrl = new URL(databaseUrl);

if (parsedUrl.pathname !== '/app_test') {
  throw new Error(
    'Backend integration tests must use the app_test database.'
  );
}

// Importing the pool above is safe even when these checks fail: pg only opens
// a connection on the first query, and a failed check stops the run before
// any test can send one.

// Close the shared connection pool once a test file finishes, so individual
// test files don't have to remember to.
afterAll(async () => {
  await pool.end();
});
